// FUSE Relight RL-5.1: the path tracer on the GPU (see pt_gpu.hpp).
#include <fuse/relight/render/pathtrace/pt_gpu.hpp>

#include <fuse/relight/render/material/bsdf_host.hpp>
#include <fuse/renderer/rt/rt_caps.hpp>
#include <fuse/renderer/vk/allocator.hpp>
#include <fuse/renderer/vk/device.hpp>

#include <algorithm>
#include <cstring>

#if defined(FUSE_VULKAN_BACKEND)
#include <vulkan/vulkan.h>

// Generated by render/pathtrace/embed_spirv.cmake: kRlPtTrace{Slang,Glsl}Spv and FUSE_RL_PT_{SLANG,GLSL}.
#include "rl_pt_spv.h"
#endif

namespace fuse::relight::render::pathtrace {

namespace rr = fuse::renderer;
namespace rg = fuse::renderer::rg;
namespace gs = fuse::renderer::gpu_scene;

namespace {
constexpr u32 kGroup = 8u;
constexpr u64 kWordBytes = sizeof(Word);

u64 align256(u64 v) { return (v + 255u) & ~u64{255u}; }

u32 storageUsage() {
    return static_cast<u32>(rr::BufferUsage::Storage) | static_cast<u32>(rr::BufferUsage::ShaderDeviceAddress) |
           static_cast<u32>(rr::BufferUsage::TransferSrc);
}
} // namespace

static_assert(sizeof(Word) == 16u, "packed words");

PathTracerGpu::PathTracerGpu() = default;
PathTracerGpu::~PathTracerGpu() { destroy(); }

bool PathTracerGpu::init(const PathTracerGpuDesc& desc) {
    destroy();
    m_desc = desc;
#if defined(FUSE_VULKAN_BACKEND)
    if (desc.device == nullptr || desc.allocator == nullptr || desc.upload == nullptr || desc.bindless == nullptr ||
        desc.framesInFlight == 0u || desc.framesInFlight > kMaxSlots) {
        m_reason = "incomplete PathTracerGpuDesc";
        return false;
    }
    const rr::rt::RtCapabilities caps = rr::rt::queryRtCapabilities(desc.device);
    if (!caps.usable) {
        m_reason = caps.reason;
        return false;
    }
    lights::RelightLightsGpuDesc ld{};
    ld.device = desc.device;
    ld.allocator = desc.allocator;
    ld.bindless = desc.bindless;
    ld.language = desc.language == PtKernelLanguage::Glsl    ? lights::LightKernelLanguage::Glsl
                  : desc.language == PtKernelLanguage::Slang ? lights::LightKernelLanguage::Slang
                                                             : lights::LightKernelLanguage::Auto;
    ld.framesInFlight = desc.framesInFlight;
    ld.initialLights = 64;
    m_retired.reserve(16);
    m_initialized = true; // destroy() releases partial state from here on
    if (!m_lights.init(ld)) {
        m_reason = "RelightLightsGpu init failed (light tree GPU path)";
        destroy();
        return false;
    }
    if (!createPipeline()) {
        m_reason = "no path-tracing kernel of the requested language / pipeline creation failed";
        destroy();
        return false;
    }
    m_reason = "ok";
    return true;
#else
    m_reason = "stub backend";
    return false;
#endif
}

void PathTracerGpu::releaseScene() {
    if (m_as != nullptr) {
        m_as->destroy();
        m_as.reset();
    }
    if (m_scene != nullptr) {
        m_scene->destroy();
        m_scene.reset();
    }
    m_handles.clear();
    m_meshSignature.clear();
    m_sceneReady = false;
}

void PathTracerGpu::destroy() {
    if (!m_initialized) {
        return;
    }
#if defined(FUSE_VULKAN_BACKEND)
    collectRetired(~0ull);
    releaseScene();
    m_lights.destroy();
    for (rr::Buffer* b : {&m_statics, &m_ring, &m_outputs}) {
        if (b->handle != nullptr) {
            m_desc.allocator->destroyBuffer(*b);
        }
        *b = rr::Buffer{};
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    if (m_pipeline != nullptr) {
        vkDestroyPipeline(device, static_cast<VkPipeline>(m_pipeline), nullptr);
    }
    if (m_layoutHandle != nullptr) {
        vkDestroyPipelineLayout(device, static_cast<VkPipelineLayout>(m_layoutHandle), nullptr);
    }
#endif
    m_pipeline = nullptr;
    m_layoutHandle = nullptr;
    m_retired.clear();
    m_language = "none";
    m_stats = PathTracerGpuStats{};
    m_initialized = false;
}

bool PathTracerGpu::createPipeline() {
#if defined(FUSE_VULKAN_BACKEND)
    const u32* words = nullptr;
    usize bytes = 0;
#if defined(FUSE_RL_PT_SLANG)
    if (m_desc.language == PtKernelLanguage::Auto || m_desc.language == PtKernelLanguage::Slang) {
        words = kRlPtTraceSlangSpv;
        bytes = sizeof(kRlPtTraceSlangSpv);
        m_language = "slang";
    }
#endif
#if defined(FUSE_RL_PT_GLSL)
    if (words == nullptr && (m_desc.language == PtKernelLanguage::Auto || m_desc.language == PtKernelLanguage::Glsl)) {
        words = kRlPtTraceGlslSpv;
        bytes = sizeof(kRlPtTraceGlslSpv);
        m_language = "glsl";
    }
#endif
    if (words == nullptr) {
        return false;
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    VkDescriptorSetLayout setLayout = static_cast<VkDescriptorSetLayout>(m_desc.bindless->layoutHandle());
    VkPushConstantRange range{VK_SHADER_STAGE_COMPUTE_BIT, 0, static_cast<u32>(sizeof(TracePush))};
    VkPipelineLayoutCreateInfo layoutInfo{};
    layoutInfo.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
    layoutInfo.setLayoutCount = 1u;
    layoutInfo.pSetLayouts = &setLayout;
    layoutInfo.pushConstantRangeCount = 1;
    layoutInfo.pPushConstantRanges = &range;
    VkPipelineLayout layout = VK_NULL_HANDLE;
    if (vkCreatePipelineLayout(device, &layoutInfo, nullptr, &layout) != VK_SUCCESS) {
        return false;
    }
    m_layoutHandle = layout;
    VkShaderModuleCreateInfo moduleInfo{};
    moduleInfo.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
    moduleInfo.codeSize = bytes;
    moduleInfo.pCode = words;
    VkShaderModule module = VK_NULL_HANDLE;
    if (vkCreateShaderModule(device, &moduleInfo, nullptr, &module) != VK_SUCCESS) {
        return false;
    }
    VkComputePipelineCreateInfo info{};
    info.sType = VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO;
    info.flags = static_cast<VkPipelineCreateFlags>(m_desc.bindless->pipelineCreateFlags());
    info.stage.sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
    info.stage.stage = VK_SHADER_STAGE_COMPUTE_BIT;
    info.stage.module = module;
    info.stage.pName = "main";
    info.layout = layout;
    VkPipeline pipeline = VK_NULL_HANDLE;
    const VkResult result = vkCreateComputePipelines(device, VK_NULL_HANDLE, 1, &info, nullptr, &pipeline);
    vkDestroyShaderModule(device, module, nullptr);
    m_pipeline = pipeline;
    return result == VK_SUCCESS;
#else
    return false;
#endif
}

bool PathTracerGpu::ensureBuffer(rr::Buffer& buffer, u64 bytes, u32 usage, u32 memory, const char* name, u8* queue) {
    if (buffer.handle != nullptr && bytes <= buffer.desc.size) {
        return true;
    }
    rr::BufferDesc d{};
    d.size = static_cast<usize>(bytes);
    d.usage = static_cast<rr::BufferUsage>(usage);
    d.memoryUsage = static_cast<rr::MemoryUsage>(memory);
    d.name = name;
    rr::Buffer fresh{};
    if (!m_desc.allocator->createBuffer(d, fresh) || fresh.mapped == nullptr || fresh.deviceAddress == 0u) {
        if (fresh.handle != nullptr) {
            m_desc.allocator->destroyBuffer(fresh);
        }
        return false;
    }
    if (buffer.handle != nullptr) {
        m_retired.push_back(Retired{buffer, m_frameSerial});
        ++m_stats.reallocations;
    }
    buffer = fresh;
    if (queue != nullptr) {
        *queue = rg::kNoQueue;
    }
    return true;
}

bool PathTracerGpu::rebuildScene(PtCompiledScene& scene) {
    releaseScene();
    m_scene = std::make_unique<gs::GpuScene>();
    gs::GpuSceneDesc sd{};
    sd.device = m_desc.device;
    sd.allocator = m_desc.allocator;
    sd.upload = m_desc.upload;
    sd.instanceCapacity = std::max(scene.instanceCount(), 16u);
    sd.meshCapacity = std::max(scene.meshCount(), 16u);
    sd.materialCapacity = 16u;
    sd.lightCapacity = 16u;
    if (!m_scene->init(sd) || !m_scene->gpuEnabled()) {
        m_reason = "GpuScene init failed";
        return false;
    }
    m_scene->beginFrame(m_frameSerial);
    for (u32 m = 0; m < scene.meshCount(); ++m) {
        if (m_scene->addMeshletMesh(scene.meshlets(m)) != m) {
            m_reason = "addMeshletMesh failed";
            return false;
        }
    }
    std::vector<u32> slots(scene.instanceCount());
    m_handles.resize(scene.instanceCount());
    for (u32 i = 0; i < scene.instanceCount(); ++i) {
        const PtInstance& inst = scene.instance(i);
        gs::InstanceDesc id{};
        id.mesh = inst.mesh;
        id.material = 0;
        id.flags = ((inst.flags & kPtInstanceVisible) != 0u ? gs::kInstanceVisible : 0u) |
                   ((inst.flags & kPtInstanceShadow) != 0u ? gs::kInstanceCastShadow : 0u);
        for (u32 r = 0; r < 3u; ++r) {
            for (u32 c = 0; c < 4u; ++c) {
                id.transform.rows[r][c] = inst.objectToWorld[r * 4u + c];
            }
        }
        m_handles[i] = m_scene->addInstance(id);
        if (!m_handles[i].valid()) {
            m_reason = "addInstance failed";
            return false;
        }
        slots[i] = m_handles[i].slot;
    }
    if (!scene.setSlots(slots)) {
        m_reason = "slot assignment failed";
        return false;
    }
    m_as = std::make_unique<rr::rt::AccelerationStructures>();
    rr::rt::AccelerationStructuresDesc ad{};
    ad.device = m_desc.device;
    ad.allocator = m_desc.allocator;
    ad.upload = m_desc.upload;
    ad.scene = m_scene.get();
    ad.instanceCapacity = sd.instanceCapacity;
    ad.meshCapacity = sd.meshCapacity;
    ad.bindless = m_desc.bindless;
    ad.language = m_desc.language == PtKernelLanguage::Glsl    ? rr::rt::RtKernelLanguage::Glsl
                  : m_desc.language == PtKernelLanguage::Slang ? rr::rt::RtKernelLanguage::Slang
                                                               : rr::rt::RtKernelLanguage::Auto;
    ad.name = "relight.pt.rt";
    if (!m_as->init(ad)) {
        m_reason = m_as->reason();
        return false;
    }
    // Static tables: triangle words + the albedo table.
    const material::AlbedoLut& lut = material::sharedAlbedoLut();
    if (!lut.valid()) {
        m_reason = "albedo table";
        return false;
    }
    const u64 triBytes = std::max<u64>(scene.triangleWords().size() * kWordBytes, 16u);
    m_trianglesOffset = 0;
    m_lutOffset = align256(triBytes);
    const u64 staticBytes = m_lutOffset + align256(u64(lut.size()) * sizeof(float));
    if (m_statics.handle != nullptr) {
        m_retired.push_back(Retired{m_statics, m_frameSerial});
        m_statics = rr::Buffer{};
    }
    if (!ensureBuffer(m_statics, staticBytes, storageUsage(), static_cast<u32>(rr::MemoryUsage::CpuToGpu),
                      "relight.pt.statics", &m_staticsQueue)) {
        m_reason = "static table buffer";
        return false;
    }
    u8* base = static_cast<u8*>(m_statics.mapped);
    if (!scene.triangleWords().empty()) {
        std::memcpy(base + m_trianglesOffset, scene.triangleWords().data(),
                    scene.triangleWords().size() * kWordBytes);
    }
    std::memcpy(base + m_lutOffset, lut.data(), std::size_t(lut.size()) * sizeof(float));
    m_meshSignature.clear();
    for (u32 m = 0; m < scene.meshCount(); ++m) {
        m_meshSignature.push_back(scene.meshlets(m).triangle_count());
    }
    for (u32 i = 0; i < scene.instanceCount(); ++i) {
        m_meshSignature.push_back(scene.instance(i).mesh);
    }
    m_sceneReady = true;
    ++m_stats.sceneBuilds;
    return true;
}

bool PathTracerGpu::setScene(PtCompiledScene& scene) {
    if (!m_initialized || !scene.valid()) {
        return false;
    }
    bool same = m_sceneReady && m_meshSignature.size() == std::size_t(scene.meshCount()) + scene.instanceCount();
    for (u32 m = 0; same && m < scene.meshCount(); ++m) {
        same = m_meshSignature[m] == scene.meshlets(m).triangle_count();
    }
    for (u32 i = 0; same && i < scene.instanceCount(); ++i) {
        same = m_meshSignature[scene.meshCount() + i] == scene.instance(i).mesh;
    }
    if (!same) {
        return rebuildScene(scene);
    }
    // Same structure: the slots stay; the compiled scene keeps them (setSlots only after a rebuild).
    return true;
}

bool PathTracerGpu::beginFrame(u64 frameSerial, const PtCompiledScene& scene, const PtFrameDesc& frame) {
    if (!m_initialized || !m_sceneReady || frame.width == 0u || frame.height == 0u) {
        return false;
    }
    m_frameSerial = frameSerial;
    m_stats.tracePasses = 0;
    m_lightsAdded = false;
    m_restirDiAddress = 0;
    m_restirDiBuffer = rg::BufferRef{};
    m_restirGiAddress = 0;
    m_restirGiBuffer = rg::BufferRef{};
    m_rcBuffer = rg::BufferRef{};
    // GPU scene: instance transforms / flags of this frame (the compiled scene is authoritative).
    m_scene->beginFrame(frameSerial);
    m_as->beginFrame(frameSerial);
    for (u32 i = 0; i < scene.instanceCount(); ++i) {
        const PtInstance& inst = scene.instance(i);
        const u32 slot = m_handles[i].slot;
        const gs::GpuTransform& cur = m_scene->transform(slot);
        bool moved = false;
        for (u32 r = 0; r < 3u && !moved; ++r) {
            for (u32 c = 0; c < 4u; ++c) {
                if (cur.rows[r][c] != inst.objectToWorld[r * 4u + c]) {
                    moved = true;
                    break;
                }
            }
        }
        if (moved) {
            gs::GpuTransform t{};
            for (u32 r = 0; r < 3u; ++r) {
                for (u32 c = 0; c < 4u; ++c) {
                    t.rows[r][c] = inst.objectToWorld[r * 4u + c];
                }
            }
            m_scene->setTransform(m_handles[i], t);
        }
        const u32 flags = gs::kInstanceValid |
                          ((inst.flags & kPtInstanceVisible) != 0u ? gs::kInstanceVisible : 0u) |
                          ((inst.flags & kPtInstanceShadow) != 0u ? gs::kInstanceCastShadow : 0u);
        if (m_scene->instance(slot).flags != flags) {
            m_scene->setInstanceFlags(m_handles[i], flags & ~gs::kInstanceValid);
        }
    }
    if (!m_scene->commit().ok || !m_as->commit().ok) {
        m_reason = "scene / acceleration-structure commit failed";
        return false;
    }
    if (!m_lights.beginFrame(frameSerial, scene.lightSet())) {
        m_reason = "light ring";
        return false;
    }
    m_lightCount = scene.lightSet().lightCount();
    // Ring slot.
    RingLayout l{};
    u64 cursor = 0;
    auto take = [&](u64 bytes) {
        const u64 at = cursor;
        cursor = align256(cursor + std::max<u64>(bytes, 16u));
        return at;
    };
    l.params = take(kPtParamWords * kWordBytes);
    l.instances = take(scene.instanceWords().size() * kWordBytes);
    l.materials = take(scene.materialWords().size() * kWordBytes);
    l.portals = take(scene.portalWords().size() * kWordBytes);
    l.lightMap = take(std::max<std::size_t>(scene.lightMap().size(), 1u) * sizeof(float));
    l.bytes = cursor;
    if (m_ring.handle == nullptr || l.bytes > m_slotStride) {
        const u64 stride = align256(std::max<u64>(l.bytes + l.bytes / 2u, 4096u));
        if (m_ring.handle != nullptr) {
            m_retired.push_back(Retired{m_ring, frameSerial});
            m_ring = rr::Buffer{};
            ++m_stats.reallocations;
        }
        if (!ensureBuffer(m_ring, stride * m_desc.framesInFlight, storageUsage(),
                          static_cast<u32>(rr::MemoryUsage::CpuToGpu), "relight.pt.ring", &m_ringQueue)) {
            m_reason = "ring buffer";
            return false;
        }
        m_slotStride = stride;
    }
    m_ringLayout = l;
    m_slot = static_cast<u32>(frameSerial % m_desc.framesInFlight);
    u8* slot = static_cast<u8*>(m_ring.mapped) + u64(m_slot) * m_slotStride;
    Word params[kPtParamWords];
    scene.packParams(frame.settings, frame.width, frame.height, frame.frameSeed, frame.sampleBase, params);
    std::memcpy(slot + l.params, params, sizeof(params));
    std::memcpy(slot + l.instances, scene.instanceWords().data(), scene.instanceWords().size() * kWordBytes);
    std::memcpy(slot + l.materials, scene.materialWords().data(), scene.materialWords().size() * kWordBytes);
    std::memcpy(slot + l.portals, scene.portalWords().data(), scene.portalWords().size() * kWordBytes);
    if (!scene.lightMap().empty()) {
        std::memcpy(slot + l.lightMap, scene.lightMap().data(), scene.lightMap().size() * sizeof(float));
    }
    m_stats.uploadBytes += l.bytes;
    // Outputs.
    const u64 stride = align256(u64(frame.width) * frame.height * 16u);
    const u64 outBytes = stride * kPtOutSections;
    const bool resized = frame.width != m_width || frame.height != m_height;
    if (m_outputs.handle == nullptr || outBytes > m_outputs.desc.size) {
        if (!ensureBuffer(m_outputs, outBytes, storageUsage(), static_cast<u32>(rr::MemoryUsage::GpuToCpu),
                          "relight.pt.outputs", &m_outputsQueue)) {
            m_reason = "output buffer";
            return false;
        }
    }
    m_outStride = stride;
    m_width = frame.width;
    m_height = frame.height;
    m_accumulate = frame.accumulate && !resized;
    ++m_stats.frames;
    return true;
}

PtGraphRefs PathTracerGpu::importInto(rg::Graph& graph) {
    PtGraphRefs refs{};
    if (!m_initialized || !m_sceneReady || m_ring.handle == nullptr || m_outputs.handle == nullptr) {
        return refs;
    }
    refs.scene = m_scene->importInto(graph);
    refs.rt = m_as->importInto(graph, refs.scene);
    refs.lights = m_lights.importInto(graph);
    refs.statics = graph.importBuffer(rg::ImportedBuffer{m_statics.handle, m_statics.desc.size, m_staticsQueue,
                                                         &m_staticsQueue, "relight.pt.statics"});
    refs.ring = graph.importBuffer(
        rg::ImportedBuffer{m_ring.handle, m_ring.desc.size, m_ringQueue, &m_ringQueue, "relight.pt.ring"});
    refs.ringRange = rg::BufferRange{u64(m_slot) * m_slotStride, m_ringLayout.bytes};
    refs.outputs = graph.importBuffer(rg::ImportedBuffer{m_outputs.handle, m_outputs.desc.size, m_outputsQueue,
                                                         &m_outputsQueue, "relight.pt.outputs"});
    refs.valid = refs.rt.tlas.valid() && refs.lights.ring.valid();
    return refs;
}

bool PathTracerGpu::addLightsPass(rg::Graph& graph, const PtGraphRefs& refs) {
    if (!m_initialized || !refs.valid) {
        return false;
    }
    if (m_lightsAdded) {
        return true;
    }
    m_lightsAdded = m_lights.addConvertPass(graph, refs.lights);
    return m_lightsAdded;
}

PtTraceBindings PathTracerGpu::traceBindings() const {
    PtTraceBindings b{};
    if (!m_initialized || !m_sceneReady || m_ring.handle == nullptr) {
        return b;
    }
    const u64 slotBase = m_ring.deviceAddress + u64(m_slot) * m_slotStride;
    b.params = slotBase + m_ringLayout.params;
    b.instances = slotBase + m_ringLayout.instances;
    b.triangles = m_statics.deviceAddress + m_trianglesOffset;
    b.materials = slotBase + m_ringLayout.materials;
    b.portals = slotBase + m_ringLayout.portals;
    b.lightMap = slotBase + m_ringLayout.lightMap;
    b.lightTable = m_lights.tableAddress();
    b.lightTree = m_lights.treeHeaderAddress();
    b.tlas = m_as->tlasAddress();
    b.lut = m_statics.deviceAddress + m_lutOffset;
    b.lightCount = m_lightCount;
    b.width = m_width;
    b.height = m_height;
    return b;
}

void PathTracerGpu::setRestirDi(u64 address, rg::BufferRef buffer, rg::BufferRange range) {
    m_restirDiAddress = address;
    m_restirDiBuffer = buffer;
    m_restirDiRange = range;
}

void PathTracerGpu::setRestirGi(u64 address, rg::BufferRef buffer, rg::BufferRange range) {
    m_restirGiAddress = address;
    m_restirGiBuffer = buffer;
    m_restirGiRange = range;
}

bool PathTracerGpu::setRadianceCache(u64 address, rg::BufferRef buffer, rg::BufferRange range) {
    if (!m_initialized || m_ring.mapped == nullptr || (address & 255u) != 0u || (address >> 56u) != 0u ||
        !buffer.valid()) {
        return false;
    }
    // PtParams.rcTableLo / rcTableHi (pt_reference_types.h): w10.z = bits 8..31, w10.w = bits 32..55 (exact floats).
    Word* params = reinterpret_cast<Word*>(static_cast<u8*>(m_ring.mapped) + u64(m_slot) * m_slotStride +
                                           m_ringLayout.params);
    params[10].z = float(u32((address >> 8u) & 0xFFFFFFu));
    params[10].w = float(u32((address >> 32u) & 0xFFFFFFu));
    m_rcBuffer = buffer;
    m_rcRange = range;
    return true;
}

bool PathTracerGpu::addTracePass(rg::Graph& graph, const PtGraphRefs& refs) {
    if (!m_initialized || !refs.valid) {
        return false;
    }
    if (!addLightsPass(graph, refs)) {
        return false;
    }
    const PtTraceBindings b = traceBindings();
    PassRecord& r = m_record;
    r = PassRecord{};
    r.self = this;
    r.push.params = b.params;
    r.push.instances = b.instances;
    r.push.triangles = b.triangles;
    r.push.materials = b.materials;
    r.push.portals = b.portals;
    r.push.lightMap = b.lightMap;
    r.push.lightTable = refs.lights.tableAddress;
    r.push.lightTree = refs.lights.tree.header;
    r.push.tlas = b.tlas;
    r.push.lut = b.lut;
    r.push.restirDi = m_restirDiBuffer.valid() ? m_restirDiAddress : 0u;
    r.push.restirGi = m_restirGiBuffer.valid() ? m_restirGiAddress : 0u;
    r.push.outputs = m_outputs.deviceAddress;
    r.push.outStride = m_outStride;
    r.push.width = m_width;
    r.push.height = m_height;
    r.push.accumulate = m_accumulate ? 1u : 0u;
    r.push.lightCount = m_lightCount;
    r.groupsX = (m_width + kGroup - 1u) / kGroup;
    r.groupsY = (m_height + kGroup - 1u) / kGroup;
    ++m_stats.tracePasses;
    rg::PassBuilder pass = graph.addPass("relight.pt.trace", &PathTracerGpu::recordTrace, &r);
    pass.use(refs.rt.tlas, rg::Access::AccelerationStructureRead, {}, rg::kStageCompute)
        .use(refs.statics, rg::Access::StorageRead, {}, rg::kStageCompute)
        .use(refs.ring, rg::Access::StorageRead, refs.ringRange, rg::kStageCompute)
        .use(refs.lights.ring, rg::Access::StorageRead, refs.lights.tableRange, rg::kStageCompute)
        .use(refs.outputs, m_accumulate ? rg::Access::StorageReadWrite : rg::Access::StorageWrite,
             rg::BufferRange{0u, m_outStride * kPtOutSections}, rg::kStageCompute);
    if (refs.lights.tree.tree.valid()) {
        pass.use(refs.lights.tree.tree, rg::Access::StorageRead, refs.lights.tree.range, rg::kStageCompute);
    }
    if (m_restirDiBuffer.valid()) {
        pass.use(m_restirDiBuffer, rg::Access::StorageRead, m_restirDiRange, rg::kStageCompute);
    }
    if (m_restirGiBuffer.valid()) {
        pass.use(m_restirGiBuffer, rg::Access::StorageRead, m_restirGiRange, rg::kStageCompute);
    }
    if (m_rcBuffer.valid()) {
        pass.use(m_rcBuffer, rg::Access::StorageReadWrite, m_rcRange, rg::kStageCompute); // RL-5.4 queries + counters
    }
    return true;
}

void PathTracerGpu::recordTrace(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const PassRecord& r = *static_cast<const PassRecord*>(user);
    const PathTracerGpu& self = *r.self;
    VkCommandBuffer cmd = static_cast<VkCommandBuffer>(context.commandBuffer);
    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, static_cast<VkPipeline>(self.m_pipeline));
    self.m_desc.bindless->bind(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, self.m_layoutHandle, 0);
    vkCmdPushConstants(cmd, static_cast<VkPipelineLayout>(self.m_layoutHandle), VK_SHADER_STAGE_COMPUTE_BIT, 0,
                       static_cast<u32>(sizeof(TracePush)), &r.push);
    vkCmdDispatch(cmd, r.groupsX, r.groupsY, 1u);
#else
    (void)context;
    (void)user;
#endif
}

u32 PathTracerGpu::collectRetired(u64 completedSerial) {
    u32 collected = m_lights.collectRetired(completedSerial);
    if (m_scene != nullptr) {
        collected += m_scene->collectRetired(completedSerial);
    }
    if (m_as != nullptr) {
        collected += m_as->collectRetired(completedSerial);
    }
    usize keep = 0;
    for (usize i = 0; i < m_retired.size(); ++i) {
        if (m_retired[i].serial > completedSerial) {
            m_retired[keep++] = m_retired[i];
            continue;
        }
        if (m_retired[i].buffer.handle != nullptr) {
            m_desc.allocator->destroyBuffer(m_retired[i].buffer);
        }
        ++collected;
    }
    m_retired.resize(keep);
    return collected;
}

const void* PathTracerGpu::mappedOutputs() const { return m_outputs.mapped; }

u64 PathTracerGpu::outputAddress(u32 section) const { return m_outputs.deviceAddress + u64(section) * m_outStride; }

} // namespace fuse::relight::render::pathtrace
